-- =============================================================================
-- seed.sql — test data for local development (`supabase db reset` runs this).
--
-- Creates: 1 admin, 2 brands (1 active campaign each), 3 creators,
-- approved matches (affiliate links auto-generated by trigger), a few
-- conversions, and some click events.
--
-- All users share the password: password123
-- =============================================================================

-- pgcrypto provides crypt()/gen_salt() for the password hashes below.
create extension if not exists pgcrypto;

-- ---------------------------------------------------------------------------
-- Fixed UUIDs so we can wire relationships deterministically.
-- ---------------------------------------------------------------------------
-- auth.users / profiles
--   admin    : 00000000-0000-0000-0000-000000000001
--   brand 1  : 00000000-0000-0000-0000-000000000011
--   brand 2  : 00000000-0000-0000-0000-000000000012
--   creator 1: 00000000-0000-0000-0000-000000000021
--   creator 2: 00000000-0000-0000-0000-000000000022
--   creator 3: 00000000-0000-0000-0000-000000000023

-- ---------------------------------------------------------------------------
-- auth.users — the on_auth_user_created trigger creates the matching profiles
-- from raw_user_meta_data (role + full_name).
-- ---------------------------------------------------------------------------
insert into auth.users (
  instance_id, id, aud, role, email, encrypted_password,
  email_confirmed_at, raw_app_meta_data, raw_user_meta_data,
  created_at, updated_at
)
values
  ('00000000-0000-0000-0000-000000000000', '00000000-0000-0000-0000-000000000001',
   'authenticated', 'authenticated', 'admin@example.com', crypt('password123', gen_salt('bf')),
   now(), '{"provider":"email","providers":["email"]}',
   '{"role":"admin","full_name":"Platform Admin"}', now(), now()),

  ('00000000-0000-0000-0000-000000000000', '00000000-0000-0000-0000-000000000011',
   'authenticated', 'authenticated', 'brand1@example.com', crypt('password123', gen_salt('bf')),
   now(), '{"provider":"email","providers":["email"]}',
   '{"role":"brand","full_name":"Glow Cosmetics"}', now(), now()),

  ('00000000-0000-0000-0000-000000000000', '00000000-0000-0000-0000-000000000012',
   'authenticated', 'authenticated', 'brand2@example.com', crypt('password123', gen_salt('bf')),
   now(), '{"provider":"email","providers":["email"]}',
   '{"role":"brand","full_name":"TechZone TN"}', now(), now()),

  ('00000000-0000-0000-0000-000000000000', '00000000-0000-0000-0000-000000000021',
   'authenticated', 'authenticated', 'creator1@example.com', crypt('password123', gen_salt('bf')),
   now(), '{"provider":"email","providers":["email"]}',
   '{"role":"creator","full_name":"Adam Cheikhrouhou"}', now(), now()),

  ('00000000-0000-0000-0000-000000000000', '00000000-0000-0000-0000-000000000022',
   'authenticated', 'authenticated', 'creator2@example.com', crypt('password123', gen_salt('bf')),
   now(), '{"provider":"email","providers":["email"]}',
   '{"role":"creator","full_name":"Sarra Ben Ali"}', now(), now()),

  ('00000000-0000-0000-0000-000000000000', '00000000-0000-0000-0000-000000000023',
   'authenticated', 'authenticated', 'creator3@example.com', crypt('password123', gen_salt('bf')),
   now(), '{"provider":"email","providers":["email"]}',
   '{"role":"creator","full_name":"Yassine Tech"}', now(), now())
on conflict (id) do nothing;

-- GoTrue scans these token columns as Go strings on login; NULL -> 500
-- "Database error querying schema". Manual SQL inserts leave them NULL, so
-- normalise them to '' (the value GoTrue itself uses for new signups).
update auth.users set
  confirmation_token         = coalesce(confirmation_token, ''),
  recovery_token             = coalesce(recovery_token, ''),
  email_change               = coalesce(email_change, ''),
  email_change_token_new     = coalesce(email_change_token_new, ''),
  email_change_token_current = coalesce(email_change_token_current, ''),
  phone_change               = coalesce(phone_change, ''),
  phone_change_token         = coalesce(phone_change_token, ''),
  reauthentication_token     = coalesce(reauthentication_token, '')
where id in (
  '00000000-0000-0000-0000-000000000001',
  '00000000-0000-0000-0000-000000000011',
  '00000000-0000-0000-0000-000000000012',
  '00000000-0000-0000-0000-000000000021',
  '00000000-0000-0000-0000-000000000022',
  '00000000-0000-0000-0000-000000000023'
);

-- Email identities so the seeded users can actually sign in.
insert into auth.identities (
  provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at
)
select
  u.id, u.id,
  jsonb_build_object('sub', u.id::text, 'email', u.email),
  'email', now(), now(), now()
from auth.users u
where u.id in (
  '00000000-0000-0000-0000-000000000001',
  '00000000-0000-0000-0000-000000000011',
  '00000000-0000-0000-0000-000000000012',
  '00000000-0000-0000-0000-000000000021',
  '00000000-0000-0000-0000-000000000022',
  '00000000-0000-0000-0000-000000000023'
)
on conflict do nothing;

-- Safety net: ensure profiles exist with correct role/name even if the
-- trigger was not active when users were inserted.
insert into profiles (id, role, full_name, email)
values
  ('00000000-0000-0000-0000-000000000001', 'admin',   'Platform Admin',     'admin@example.com'),
  ('00000000-0000-0000-0000-000000000011', 'brand',   'Glow Cosmetics',     'brand1@example.com'),
  ('00000000-0000-0000-0000-000000000012', 'brand',   'TechZone TN',        'brand2@example.com'),
  ('00000000-0000-0000-0000-000000000021', 'creator', 'Adam Cheikhrouhou',  'creator1@example.com'),
  ('00000000-0000-0000-0000-000000000022', 'creator', 'Sarra Ben Ali',      'creator2@example.com'),
  ('00000000-0000-0000-0000-000000000023', 'creator', 'Yassine Tech',       'creator3@example.com')
on conflict (id) do update
  set role = excluded.role, full_name = excluded.full_name, email = excluded.email;

