-- ---------------------------------------------------------------------------
-- Matches — inserting with status 'approved' fires the trigger that
-- auto-generates an affiliate_link for each.
-- ---------------------------------------------------------------------------
insert into matches (id, campaign_id, creator_id, status)
values
  ('aa000000-0000-0000-0000-000000000001', 'ca000000-0000-0000-0000-000000000001', 'c0000000-0000-0000-0000-000000000001', 'approved'),
  ('aa000000-0000-0000-0000-000000000002', 'ca000000-0000-0000-0000-000000000001', 'c0000000-0000-0000-0000-000000000002', 'approved'),
  ('aa000000-0000-0000-0000-000000000003', 'ca000000-0000-0000-0000-000000000002', 'c0000000-0000-0000-0000-000000000003', 'approved')
on conflict (id) do nothing;

-- ---------------------------------------------------------------------------
-- Conversions — ref the auto-generated affiliate links by lookup.
-- The before-insert trigger fills commission_amount / platform_fee and bumps
-- campaign.spent, so we only provide sale_amount + status.
-- ---------------------------------------------------------------------------
insert into conversions (affiliate_link_id, campaign_id, creator_id, brand_id, order_reference, sale_amount, source, status)
select al.id, al.campaign_id, al.creator_id, c.brand_id, v.order_reference, v.sale_amount, 'sheet', v.status::conversion_status
from (values
  ('aa000000-0000-0000-0000-000000000001', 'ORD-1001', 120.0, 'confirmed'),
  ('aa000000-0000-0000-0000-000000000001', 'ORD-1002',  80.0, 'confirmed'),
  ('aa000000-0000-0000-0000-000000000002', 'ORD-1003', 150.0, 'pending'),
  ('aa000000-0000-0000-0000-000000000003', 'ORD-2001', 220.0, 'confirmed')
) as v(match_id, order_reference, sale_amount, status)
join affiliate_links al on al.match_id = v.match_id::uuid
join campaigns c on c.id = al.campaign_id
on conflict (order_reference) where order_reference is not null do nothing;

-- ---------------------------------------------------------------------------
-- Click events — a handful per affiliate link.
-- ---------------------------------------------------------------------------
insert into click_events (affiliate_link_id, ip_address, user_agent, device, country)
select al.id, '197.0.0.1'::inet,
       'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X)', 'mobile', 'TN'
from affiliate_links al, generate_series(1, 5);
